package com.ventas.integration;
import com.ventas.service.*;import com.ventas.repository.AuthStore;import com.ventas.dto.SettingsModels.*;import com.ventas.dto.ProductModels.*;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;
import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="NEGOCIO_DB_INTEGRATION",matches="true")
class SettingsDatabaseTest{
 @Autowired SettingsService service;@Autowired ProductService products;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;
 Identity actor;String code;
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusHours(1));code="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();}
 @Test void updatesActualParameterAndAudits(){var p=service.parameters(actor,false).stream().filter(x->x.clave().equals("NEGOCIO.NOMBRE_COMERCIAL")).findFirst().orElseThrow();var result=service.save(actor,"INTEGRATION_ROLLBACK",false,new Changes(List.of(new Change(p.clave(),"Nombre de prueba temporal",p.version()))));assertThat(result).anyMatch(x->x.clave().equals(p.clave())&&x.valor().equals("Nombre de prueba temporal"));assertThat(jdbc.queryForObject("select count(*) from negocio.bitacora_evento where accion='CFG.PARAMETROS' and pccre='INTEGRATION_ROLLBACK'",Long.class)).isPositive();}
 @Test void createsOrUpdatesPrintPreferencesWithoutSchemaChanges(){var p=service.parameters(actor,true).stream().filter(x->x.clave().equals("COMPROBANTE.TAMANO_TEXTO")).findFirst().orElseThrow();String next=p.valor().equals("GRANDE")?"NORMAL":"GRANDE";var result=service.save(actor,"INTEGRATION_ROLLBACK",true,new Changes(List.of(new Change(p.clave(),next,p.version()))));assertThat(result).anyMatch(x->x.clave().equals(p.clave())&&x.valor().equals(next)&&x.version()!=null);}
 @Test void createsEditsAndDeactivatesUnusedSeries(){int value=jdbc.queryForObject("select min(n) from generate_series(1,999) n where not exists(select 1 from negocio.serie_comprobante where serie='N'||lpad(n::text,3,'0'))",Integer.class);String name="N"+String.format("%03d",value);var created=service.create(actor,"INTEGRATION_ROLLBACK",new SeriesInput("N",name,10,null));assertThat(created.ultimo()).isEqualTo(9);var edited=service.update(actor,"INTEGRATION_ROLLBACK",created.id(),new SeriesInput("N",name,20,created.version()));assertThat(edited.ultimo()).isEqualTo(19);var inactive=service.state(actor,"INTEGRATION_ROLLBACK",created.id(),new State("I",edited.version()));assertThat(inactive.estado()).isEqualTo("I");}
 @Test void staleVersionsCannotOverwriteConfiguration(){var p=service.parameters(actor,false).stream().filter(x->x.clave().equals("NEGOCIO.NOMBRE_COMERCIAL")).findFirst().orElseThrow();assertThatThrownBy(()->service.save(actor,"INTEGRATION_ROLLBACK",false,new Changes(List.of(new Change(p.clave(),"Otro nombre",p.version().minusSeconds(1)))))).isInstanceOf(AuthFailure.class);}
 @Test void labelsUseRealPresentationAndInternalCode(){long category=jdbc.queryForObject("select min(id_categoria) from negocio.categoria where estado='A'",Long.class);long unit=jdbc.queryForObject("select id_unidad from negocio.unidad_medida where codigo_sunat='NIU' and estado='A'",Long.class);var product=products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(code,"Producto transaccional",null,category,unit,false,BigDecimal.ONE,BigDecimal.ONE,"GRANEL",BigDecimal.ZERO,null,"Unidad",new BigDecimal("15"),null));var details=products.details(actor,product.id());var base=details.presentaciones().getFirst();var label=service.label(actor,"INTEGRATION_ROLLBACK",new LabelRequest(product.id(),base.id(),null,3));assertThat(label.codigo()).isEqualTo(code);assertThat(label.simbologia()).isEqualTo("CODE128");assertThat(label.cantidad()).isEqualTo(3);assertThat(label.precio()).isEqualTo("15.000000");jdbc.execute("set constraints all immediate");}
}
